from pathlib import Path
import base64,json,subprocess,time,os,signal
pre=['runuser','-u','likimk','--','env','XDG_RUNTIME_DIR=/run/user/1602','DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1602/bus']
subprocess.run(pre+['systemctl','--user','stop','f8-sensor-relay.service'],check=True)
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  parts=(proc/'cmdline').read_bytes().split(b'\0')
  if b'/usr/local/lib/f8-pro/sensor-monitor.py' in parts and proc.stat().st_uid==1602:os.kill(int(proc.name),signal.SIGTERM)
 except (OSError,ProcessLookupError):pass
time.sleep(.5)
files={'usr/local/lib/f8-pro/gyro_stabilizer.py': '', 'usr/local/lib/f8-pro/sensor_fusion.py': '', 'usr/local/lib/f8-pro/sensor_examples.py': '', 'usr/local/lib/f8-pro/fusion_view.py': '', 'usr/local/lib/f8-pro/sensor-relay.py': ''}
backup=Path('/var/lib/f8-pro/backups/sensor-relay-r1')
for name,data in files.items():
 p=Path('/')/name;b=base64.b64decode(data)
 if p.exists() and not (backup/name).exists():
  old=backup/name;old.parent.mkdir(parents=True,exist_ok=True);old.write_bytes(p.read_bytes());old.chmod(p.stat().st_mode&0o777)
 p.write_bytes(b);p.chmod(0o755)
subprocess.run(pre+['systemctl','--user','start','f8-sensor-relay.service'],check=True)
png=Path('/tmp/f8-relative-stable-preview.png');status=Path('/tmp/f8-relative-stable-status.json')
r=subprocess.run(pre+['QT_QPA_PLATFORM=offscreen','/usr/bin/python3','/usr/local/lib/f8-pro/sensor-monitor.py','--preview',str(png),'--preview-tab','1','--status-json',str(status)],capture_output=True,text=True,timeout=15)
assert r.returncode==0,(r.returncode,r.stderr)
envout=subprocess.check_output(pre+['systemctl','--user','show-environment'],text=True);session={}
for line in envout.splitlines():
 if '=' in line:
  k,v=line.split('=',1)
  if k in ['DISPLAY','WAYLAND_DISPLAY','XAUTHORITY','LANG']:session[k]=v
r=subprocess.run(pre+['systemd-run','--user','--collect','--unit=f8-sensors-relative-stable-live','--setenv=QT_QPA_PLATFORM=wayland']+['--setenv='+k+'='+v for k,v in session.items()]+['/usr/local/bin/f8-sensors','--preview-tab','1'],capture_output=True,text=True,timeout=10)
time.sleep(2)
print(json.dumps({'preview':json.loads(status.read_text()),'preview_image_base64':base64.b64encode(png.read_bytes()).decode(),'launch_exit':r.returncode,'launch_message':r.stderr,'observer_active':subprocess.run(pre+['systemctl','--user','is-active','f8-sensors-relative-stable-live.service'],capture_output=True,text=True).stdout.strip(),'relay':json.loads(Path('/run/user/1602/f8-sensor-relay.json').read_text())}))
